(x, y, t) => {
  const cx = 240, cy = 120;
  const warp1 = Math.sin(x*0.012+t*0.4)*20 + Math.cos(y*0.015-t*0.3)*15;
  const warp2 = Math.cos(x*0.01-t*0.35)*18 + Math.sin(y*0.013+t*0.45)*12;
  const warp3 = Math.sin((x+y)*0.008+t*0.25)*25 + Math.cos((x-y)*0.01-t*0.2)*20;
  const sx = x + warp1 + warp3*0.3, sy = y + warp2 + warp3*0.3;
  const src = [
    [120+Math.sin(t*0.5)*90, 60+Math.cos(t*0.4)*40, 0.07, 2.1, 1.0],
    [360+Math.cos(t*0.45)*80, 60+Math.sin(t*0.55)*35, 0.085, 1.8, 0.9],
    [240+Math.sin(t*0.35+2)*110, 40+Math.cos(t*0.5+1)*30, 0.06, 2.4, 1.1],
    [80+Math.cos(t*0.6+1)*70, 160+Math.sin(t*0.5+3)*50, 0.095, 1.6, 0.85],
    [400+Math.sin(t*0.4+4)*60, 180+Math.cos(t*0.7+2)*45, 0.075, 2.0, 1.05],
    [240+Math.cos(t*0.3+5)*100, 200+Math.sin(t*0.45)*70, 0.065, 2.2, 0.95],
    [160+Math.sin(t*0.55+3)*50, 130+Math.cos(t*0.35+2)*60, 0.11, 1.4, 0.8],
    [320+Math.cos(t*0.5+1)*55, 110+Math.sin(t*0.6+4)*55, 0.1, 1.5, 0.9]
  ];
  let aS=0, iS=0, harm=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const wave = Math.sin(d*f-t*sp);
    aS += wave*w;
    iS += Math.sin(d*f*0.65+t*sp*0.5+1.7)*w;
    harm += Math.sin(d*f*1.3-t*sp*0.8+2.1)*w*0.5;
  }
  const n=8; const act=aS/n, inh=iS/n, hrm=harm/n;
  const bg1 = Math.sin(sx*0.035+sy*0.022+t*0.7);
  const bg2 = Math.sin(sx*0.028-sy*0.038+t*0.95);
  const bg3 = Math.sin((sx+sy)*0.1+t*2.2)*0.25;
  const bg4 = Math.sin((sx-sy)*0.085-t*1.8)*0.25;
  const bg = (bg1+bg2)/2+bg3+bg4;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const sp1=Math.sin(dist*0.045-ang*3.5-t*1.3);
  const sp2=Math.sin(dist*0.035+ang*4.5-t*1.0);
  const sp3=Math.sin(dist*0.06-ang*2-t*2.0)*0.3;
  const spiral=(sp1+sp2)*0.35+sp3;
  const turb=Math.sin(sx*0.08+t*1.5)*Math.cos(sy*0.09-t*1.2)*0.15;
  const feed=Math.tanh((act-inh*0.65+bg*0.25+spiral+turb+hrm*0.2)*2.0);
  const cell1=Math.sin(sx*0.14)*Math.sin(sy*0.14);
  const cell2=Math.sin((sx*0.7+sy*0.7)*0.12+t*0.8)*0.4;
  const cell3=Math.sin(sx*0.2-t*0.3)*Math.cos(sy*0.18+t*0.4)*0.2;
  const cell=Math.tanh((cell1+cell2+cell3)*1.4)*0.25;
  const ridge=Math.abs(Math.sin(dist*0.06-ang*2+t*0.8))*0.15;
  const blend=feed*0.65+cell*0.2+ridge*0.15;
  const v=blend*0.5+0.5;
  const pal=[
    [5,12,52],[12,45,95],[18,85,120],[25,130,135],
    [60,165,140],[140,190,110],[210,195,70],
    [225,150,60],[210,100,65],[180,60,70],
    [130,35,65],[70,20,55],[30,12,48],[5,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const sf=f*f*(3-2*f);
  const lum=0.82+Math.sin(feed*Math.PI)*0.18;
  const edge=Math.abs(feed)>0.65?1.12:Math.abs(feed)>0.85?1.2:1.0;
  const glow=Math.max(0,1-Math.abs(feed)*1.5)*0.15;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*lum*edge+glow*80))|0,
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*lum*edge+glow*120))|0,
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*lum*edge+glow*180))|0
  ];
}
